INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Hip 90/90 Stretch', 'Sit on the floor with your front leg bent at 90 degrees in front of you and your back leg bent at 90 degrees behind you. Keep your torso upright and gently lean forward over the front shin, then rotate to face the back leg. Hold each position for 30 seconds per side.', 'golf_specific', 'hip_mobility', ARRAY['glutes','hip_flexors','adductors'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Opens the hips for unrestricted rotation in the backswing and downswing, reducing compensatory movements that cause inconsistency and lower back pain.', 'mobility', 'https://www.youtube.com/results?search_query=hip+90+90+stretch+golf+mobility', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Open Books (Thoracic Rotation)', 'Lie on your side with knees bent and stacked, arms extended in front of you. Slowly rotate your top arm up and over, opening your chest toward the ceiling while keeping your knees together. Follow your hand with your eyes. Hold for 2 seconds and return. Perform 10-12 reps per side.', 'golf_specific', 'thoracic_mobility', ARRAY['core','back','shoulders'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Increases thoracic rotation for a fuller backswing and more power through impact, while reducing strain on the lower back.', 'mobility', 'https://www.youtube.com/results?search_query=open+books+thoracic+rotation+exercise', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Seated T-Spine Rotation', 'Sit on a bench or chair with feet flat on the floor. Cross your arms over your chest or place hands behind your head. Rotate your upper body to one side as far as comfortable, keeping your hips facing forward. Hold for 2 seconds and return. Perform 10 reps per side.', 'golf_specific', 'thoracic_mobility', ARRAY['core','obliques','back'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Isolates thoracic spine rotation by stabilizing the hips, directly improving the X-factor (hip-shoulder separation) that generates swing power.', 'mobility', 'https://www.youtube.com/results?search_query=seated+thoracic+spine+rotation+exercise', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Half-Kneeling Chop', 'Kneel with one knee down and the other foot forward. Hold a band or cable anchored high with both hands. Pull diagonally from high to low across your body toward the down-knee hip, rotating your torso. Control the return. Perform 10-12 reps per side.', 'golf_specific', 'rotational_power', ARRAY['core','obliques','shoulders','lats'], 'rotation', ARRAY['resistance_band'], 'minimal', 'intermediate', true, 'Builds the high-to-low rotational power pattern used in the downswing, training the core to transfer force from upper body to lower body efficiently.', 'stability', 'https://www.youtube.com/results?search_query=half+kneeling+chop+exercise+golf', false, ARRAY['shoulders','knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Half-Kneeling Lift', 'Kneel with one knee down, opposite foot forward. Hold a band or cable anchored low with both hands. Lift diagonally from low to high across your body, rotating your torso upward. Control the return. Perform 10-12 reps per side.', 'golf_specific', 'rotational_power', ARRAY['core','obliques','shoulders'], 'rotation', ARRAY['resistance_band'], 'minimal', 'intermediate', true, 'Trains the low-to-high rotational pattern that mirrors the follow-through phase of the golf swing, building deceleration strength to protect the spine.', 'stability', 'https://www.youtube.com/results?search_query=half+kneeling+lift+exercise', false, ARRAY['shoulders','knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Cable/Band Woodchop', 'Stand with feet shoulder-width apart, perpendicular to a cable machine or band anchor. Grip the handle with both hands and rotate your torso to pull from one side across your body to the other, pivoting on your feet. Perform 10-12 reps per side with controlled movement.', 'golf_specific', 'rotational_power', ARRAY['core','obliques','shoulders','glutes'], 'rotation', ARRAY['resistance_band'], 'minimal', 'intermediate', true, 'Develops rotational power through the transverse plane, directly mimicking the torque generation of the golf swing with progressive resistance.', 'power', 'https://www.youtube.com/results?search_query=cable+woodchop+exercise+golf', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Standing Trunk Rotation with Band', 'Anchor a resistance band at chest height. Stand sideways to the anchor, hold the band with both hands at chest level, arms extended. Rotate your torso away from the anchor point, keeping hips stable. Return with control. Perform 12-15 reps per side.', 'golf_specific', 'rotational_strength', ARRAY['core','obliques'], 'rotation', ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Builds endurance in the rotational muscles used repeatedly throughout 18 holes, helping maintain swing power and consistency on the back nine.', 'power', 'https://www.youtube.com/results?search_query=standing+trunk+rotation+band+golf', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pelvic Tilts', 'Lie on your back with knees bent and feet flat on the floor. Gently flatten your lower back against the floor by tilting your pelvis upward, then arch slightly. Move slowly between these positions. Perform 15-20 reps with controlled breathing.', 'golf_specific', 'spinal_mobility', ARRAY['core','hip_flexors','glutes'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Teaches awareness and control of pelvic position, which is fundamental to maintaining posture during the swing and preventing the S-posture and C-posture TPI faults.', 'mobility', 'https://www.youtube.com/results?search_query=pelvic+tilts+exercise+golf', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Cat-Cow', 'Start on hands and knees. Inhale as you drop your belly toward the floor, lifting your head and tailbone (cow). Exhale as you round your back toward the ceiling, tucking your chin and tailbone (cat). Flow between positions for 10-15 reps with your breath.', 'golf_specific', 'spinal_mobility', ARRAY['core','back','hip_flexors'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Mobilizes the entire spine through flexion and extension, warming up the vertebral segments that must work together for a fluid, powerful swing.', 'mobility', 'https://www.youtube.com/results?search_query=cat+cow+exercise+spinal+mobility', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dead Bug with Anti-Rotation Focus', 'Lie on your back with arms extended toward the ceiling and knees bent at 90 degrees. Press your lower back firmly into the floor. Slowly extend one arm overhead and the opposite leg toward the floor while resisting any rotation or arching. Return and switch sides. Perform 8-10 reps per side.', 'golf_specific', 'core_stability', ARRAY['core','hip_flexors','obliques'], 'anti_rotation', ARRAY[]::text[], 'none', 'intermediate', true, 'Trains the deep core stabilizers to resist rotation and extension under load, building the anti-rotation strength that protects the spine during high-speed rotational movements like the golf swing.', 'stability', 'https://www.youtube.com/results?search_query=dead+bug+anti+rotation+exercise', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pallof Press', 'Stand perpendicular to a band or cable anchored at chest height. Hold the handle at your chest with both hands. Press straight out in front of you, resisting the pull that tries to rotate your torso. Hold for 2-3 seconds and return. Perform 10-12 reps per side.', 'golf_specific', 'core_stability', ARRAY['core','obliques','shoulders'], 'anti_rotation', ARRAY['resistance_band'], 'minimal', 'intermediate', true, 'The gold standard anti-rotation exercise for golfers. Builds the core stiffness needed to transfer rotational power from the hips through the torso to the arms without energy leaks.', 'stability', 'https://www.youtube.com/results?search_query=pallof+press+exercise+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Bird Dog', 'Start on hands and knees with a neutral spine. Extend your right arm forward and left leg backward simultaneously, forming a straight line. Hold for 2-3 seconds while keeping your hips level and core braced. Return and switch sides. Perform 10 reps per side.', 'golf_specific', 'core_stability', ARRAY['core','glutes','shoulders','back'], 'anti_rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Develops contralateral stability — the ability to stabilize through opposite-side movement — which is critical for maintaining posture during the asymmetric golf swing.', 'stability', 'https://www.youtube.com/results?search_query=bird+dog+exercise+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Glute Bridge with Rotation', 'Lie on your back with knees bent and feet flat. Drive through your heels to lift your hips into a bridge. At the top, extend one arm toward the ceiling and rotate your torso toward that side. Return to center and lower. Alternate sides for 8-10 reps each.', 'golf_specific', 'hip_activation', ARRAY['glutes','core','obliques','hamstrings'], 'rotation', ARRAY[]::text[], 'none', 'intermediate', true, 'Combines glute activation with thoracic rotation at hip extension, mimicking the open-hip rotational position at impact in the golf swing.', 'stability', 'https://www.youtube.com/results?search_query=glute+bridge+rotation+exercise', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pre-Round Dynamic Warmup', 'A 5-minute dynamic warmup sequence: arm circles (10 each direction), trunk rotations (10 each side), leg swings front-to-back (10 per leg), leg swings side-to-side (10 per leg), walking lunges with rotation (5 per side), practice swings with increasing speed. Perform before every round.', 'golf_specific', 'warmup', ARRAY['core','glutes','shoulders','hip_flexors','hamstrings'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Prepares the neuromuscular system for the rotational demands of golf, increasing body temperature and joint lubrication to reduce injury risk and improve first-tee performance.', 'warmup', 'https://www.youtube.com/results?search_query=pre+round+golf+dynamic+warmup', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Post-Round Cool Down Stretch', 'A 5-minute cool down: standing quad stretch (30s each), standing hamstring stretch (30s each), cross-body shoulder stretch (30s each), standing trunk rotation (30s each), child''s pose (60s), cat-cow (10 reps). Perform after every round or practice session.', 'golf_specific', 'cooldown', ARRAY['quads','hamstrings','shoulders','back','core','hip_flexors'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Accelerates recovery by reducing muscle tension and restoring range of motion after the repetitive rotational stress of a round, helping prevent chronic tightness and injury.', 'cooldown', 'https://www.youtube.com/results?search_query=post+round+golf+cool+down+stretch', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('World''s Greatest Stretch', 'Start in a lunge position with your right foot forward. Place your left hand on the ground inside your right foot. Rotate your right arm toward the ceiling, opening your chest. Hold for 2-3 seconds, then return. Perform 5-6 reps per side.', 'mobility', 'full_body', ARRAY['hip_flexors','hamstrings','core','shoulders','back'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Addresses hip, thoracic, and shoulder mobility simultaneously — the three areas most commonly restricted in golfers over 40.', NULL, 'https://www.youtube.com/results?search_query=worlds+greatest+stretch+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pigeon Stretch', 'From hands and knees, bring your right knee forward and place it behind your right wrist with your shin angled across your body. Extend your left leg straight behind you. Keep your hips square and slowly lower your torso over the front leg. Hold for 30-45 seconds per side.', 'mobility', 'hip_mobility', ARRAY['glutes','hip_flexors','adductors'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Opens the deep external rotators of the hip that allow full hip turn in the backswing without compensating through the lower back.', NULL, 'https://www.youtube.com/results?search_query=pigeon+stretch+form', true, ARRAY['knees','hips']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Figure-4 Stretch', 'Lie on your back. Cross your right ankle over your left knee. Reach through and pull your left thigh toward your chest until you feel a stretch in your right glute. Hold for 30-45 seconds per side. Keep your head and shoulders relaxed on the floor.', 'mobility', 'hip_mobility', ARRAY['glutes','hip_flexors','adductors'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Stretches the piriformis and deep hip rotators, relieving tension that can cause sciatica and limit hip rotation.', NULL, 'https://www.youtube.com/results?search_query=figure+4+stretch+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Quadruped T-Spine Rotation', 'Start on hands and knees. Place one hand behind your head. Rotate your elbow down toward the opposite hand, then rotate up toward the ceiling as far as possible, following with your eyes. Perform 10-12 reps per side with controlled movement.', 'mobility', 'thoracic_mobility', ARRAY['core','back','obliques'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Isolates thoracic rotation with the hips and lower back stabilized, building the specific spinal mobility needed for a full shoulder turn.', NULL, 'https://www.youtube.com/results?search_query=quadruped+thoracic+spine+rotation', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Wall Slides', 'Stand with your back flat against a wall, feet 6 inches out. Press your head, upper back, elbows, and wrists against the wall. Slowly slide your arms up overhead and back down in a "Y" to "W" pattern, maintaining all contact points. Perform 10-12 reps.', 'mobility', 'shoulder_mobility', ARRAY['shoulders','rotator_cuff','traps','back'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Restores overhead shoulder mobility and scapular control that allows a full, pain-free backswing with proper arm position.', NULL, 'https://www.youtube.com/results?search_query=wall+slides+shoulder+mobility', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Couch Stretch', 'Kneel facing away from a wall or couch. Place one knee against the wall with the top of your foot against the wall. Step the other foot forward into a lunge. Squeeze the back glute and hold an upright torso. Hold for 45-60 seconds per side.', 'mobility', 'hip_mobility', ARRAY['hip_flexors','quads','glutes'], NULL, ARRAY[]::text[], 'none', 'intermediate', true, 'Deeply stretches the hip flexors and rectus femoris that become chronically tight from sitting, restoring hip extension needed for a powerful follow-through.', NULL, 'https://www.youtube.com/results?search_query=couch+stretch+hip+flexor+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Banded Pull-Aparts', 'Hold a resistance band in front of you at shoulder height with arms extended and palms facing down. Pull the band apart by squeezing your shoulder blades together until the band touches your chest. Return slowly. Perform 15-20 reps.', 'mobility', 'shoulder_mobility', ARRAY['shoulders','rotator_cuff','traps','back'], 'horizontal_pull', ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Strengthens the posterior shoulder and improves posture by counteracting the forward-rounded shoulders common in golfers and desk workers.', NULL, 'https://www.youtube.com/results?search_query=band+pull+aparts+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Foam Roll Thoracic Extension', 'Lie face-up with a foam roller positioned horizontally under your mid-back. Support your head with your hands. Gently extend backward over the roller, opening your chest toward the ceiling. Hold for 3-5 seconds, then return. Reposition the roller and repeat across 5-6 segments.', 'mobility', 'thoracic_mobility', ARRAY['back','core'], NULL, ARRAY['foam_roller'], 'minimal', 'beginner', true, 'Restores thoracic extension and rotation that deteriorates with age and sitting, directly impacting the ability to achieve a full shoulder turn.', NULL, 'https://www.youtube.com/results?search_query=foam+roll+thoracic+extension+mobility', true, ARRAY['neck']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Supine Hamstring Stretch', 'Lie on your back and lift one leg toward the ceiling. Loop a towel or band around the ball of your foot and gently pull the leg toward you while keeping the knee straight. Hold for 30-45 seconds per side. Keep the other leg flat on the floor.', 'mobility', 'hamstring_mobility', ARRAY['hamstrings','calves'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Lengthens the hamstrings that can restrict hip hinge depth and cause lower back strain during the golf address position.', NULL, 'https://www.youtube.com/results?search_query=supine+hamstring+stretch+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Ankle Circles', 'Sit or stand on one foot with the other foot elevated. Slowly draw large circles with your toes, rotating your ankle through its full range of motion. Perform 10 circles clockwise and 10 counterclockwise per ankle.', 'mobility', 'ankle_mobility', ARRAY['calves'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Maintains ankle mobility needed for a stable stance and proper weight transfer through the feet during the swing.', NULL, 'https://www.youtube.com/results?search_query=ankle+circles+mobility+exercise', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Push-ups', 'Start in a high plank with hands slightly wider than shoulder width. Lower your body until your chest nearly touches the floor, keeping your elbows at 45 degrees. Push back up to full extension. Keep your core tight and body in a straight line. Perform 10-20 reps.', 'strength', 'upper_body', ARRAY['chest','triceps','shoulders','core'], 'horizontal_push', ARRAY[]::text[], 'none', 'beginner', false, 'Builds fundamental pressing strength and core stability needed for maintaining posture throughout the swing.', NULL, 'https://www.youtube.com/results?search_query=push+ups+proper+form', true, ARRAY['wrists','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Diamond Push-ups', 'Place your hands close together under your chest, forming a diamond shape with thumbs and index fingers. Lower yourself until your chest touches your hands, keeping elbows close to your body. Push back up. Perform 8-15 reps.', 'strength', 'upper_body', ARRAY['triceps','chest','shoulders','core'], 'horizontal_push', ARRAY[]::text[], 'none', 'intermediate', false, 'Emphasizes tricep strength for arm extension speed through the impact zone of the golf swing.', NULL, 'https://www.youtube.com/results?search_query=diamond+push+ups+form', false, ARRAY['wrists','elbows']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pike Push-ups', 'Start in a downward dog position with hips high and hands shoulder-width apart. Bend your elbows to lower the top of your head toward the floor between your hands. Push back up. Keep your legs as straight as possible. Perform 8-12 reps.', 'strength', 'upper_body', ARRAY['shoulders','triceps','core'], 'vertical_push', ARRAY[]::text[], 'none', 'intermediate', false, 'Builds overhead pressing strength without weights, strengthening the deltoids that support arm positioning during the swing.', NULL, 'https://www.youtube.com/results?search_query=pike+push+ups+form', false, ARRAY['shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dumbbell Bench Press', 'Lie on a flat bench holding dumbbells at chest level with palms facing forward. Press the weights up until arms are extended, then lower under control until upper arms are parallel to the floor. Perform 8-12 reps.', 'strength', 'upper_body', ARRAY['chest','triceps','shoulders'], 'horizontal_push', ARRAY['dumbbells','bench'], 'minimal', 'intermediate', false, 'Develops pressing strength with a greater range of motion than barbell, allowing the shoulders to move more naturally.', NULL, 'https://www.youtube.com/results?search_query=dumbbell+bench+press+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dumbbell Rows', 'Place one hand and knee on a bench. Hold a dumbbell in the other hand with arm extended. Pull the weight toward your hip, driving your elbow past your torso. Squeeze your shoulder blade at the top. Lower with control. Perform 10-12 reps per side.', 'strength', 'upper_body', ARRAY['back','lats','biceps','core'], 'horizontal_pull', ARRAY['dumbbells','bench'], 'minimal', 'beginner', false, 'Builds unilateral back strength to address the asymmetric muscle imbalances caused by the one-sided golf swing.', NULL, 'https://www.youtube.com/results?search_query=dumbbell+row+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dumbbell Shoulder Press', 'Sit or stand holding dumbbells at shoulder height with palms facing forward. Press the weights overhead until arms are fully extended. Lower under control back to shoulder height. Perform 8-12 reps.', 'strength', 'upper_body', ARRAY['shoulders','triceps','core'], 'vertical_push', ARRAY['dumbbells'], 'minimal', 'intermediate', false, 'Strengthens the deltoids and scapular stabilizers for overhead arm strength and shoulder endurance during the golf swing.', NULL, 'https://www.youtube.com/results?search_query=dumbbell+shoulder+press+form', false, ARRAY['shoulders','neck']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Band Face Pulls', 'Anchor a band at face height. Grip the ends with palms facing each other. Pull toward your face, separating your hands and squeezing your shoulder blades together. Your upper arms should end parallel to the floor with elbows high. Perform 15-20 reps.', 'strength', 'upper_body', ARRAY['shoulders','rotator_cuff','traps','back'], 'horizontal_pull', ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Strengthens the posterior shoulder and external rotators, protecting against the internal rotation dominance that causes golfer''s shoulder.', NULL, 'https://www.youtube.com/results?search_query=band+face+pulls+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dumbbell Bicep Curls', 'Stand holding dumbbells at your sides with palms facing forward. Curl the weights toward your shoulders, keeping your elbows pinned to your sides. Squeeze at the top and lower under control. Perform 10-12 reps.', 'strength', 'upper_body', ARRAY['biceps','forearms'], NULL, ARRAY['dumbbells'], 'minimal', 'beginner', false, 'Builds bicep and forearm strength for grip endurance and wrist stability during repeated swings over 18 holes.', NULL, 'https://www.youtube.com/results?search_query=dumbbell+bicep+curls+form', true, ARRAY['elbows']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Overhead Tricep Extension', 'Stand or sit holding one dumbbell overhead with both hands. Lower the weight behind your head by bending your elbows, keeping your upper arms close to your ears. Extend back up to full lockout. Perform 10-12 reps.', 'strength', 'upper_body', ARRAY['triceps'], NULL, ARRAY['dumbbells'], 'minimal', 'beginner', false, 'Strengthens the triceps through a full range of motion, contributing to arm extension speed through the impact zone.', NULL, 'https://www.youtube.com/results?search_query=overhead+tricep+extension+form', true, ARRAY['elbows','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Lat Pulldown', 'Sit at a lat pulldown machine and grip the bar slightly wider than shoulder width. Pull the bar down to your upper chest, driving your elbows down and back. Squeeze your lats at the bottom and return with control. Perform 10-12 reps.', 'strength', 'upper_body', ARRAY['lats','biceps','back','forearms'], 'vertical_pull', ARRAY['lat_pulldown_machine'], 'home_gym', 'intermediate', false, 'Builds the lat width and pulling strength that drives the lead arm through the downswing for a powerful, connected swing.', NULL, 'https://www.youtube.com/results?search_query=lat+pulldown+proper+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Cable Row', 'Sit at a cable row station with feet on the platform, knees slightly bent. Pull the handle toward your lower ribcage, squeezing your shoulder blades together. Extend back with control. Keep your torso upright throughout. Perform 10-12 reps.', 'strength', 'upper_body', ARRAY['back','lats','biceps','traps','core'], 'horizontal_pull', ARRAY['cable_machine'], 'home_gym', 'intermediate', false, 'Strengthens the entire upper back and teaches the retracted scapula position needed to maintain posture through the round.', NULL, 'https://www.youtube.com/results?search_query=seated+cable+row+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Incline Dumbbell Press', 'Set a bench to 30-45 degrees. Lie back holding dumbbells at shoulder height. Press the weights up until arms are extended, then lower under control. Perform 8-12 reps.', 'strength', 'upper_body', ARRAY['chest','shoulders','triceps'], 'horizontal_push', ARRAY['dumbbells','bench'], 'home_gym', 'intermediate', false, 'Targets upper chest and anterior shoulders, building pressing strength for a stable lead arm position at the top of the backswing.', NULL, 'https://www.youtube.com/results?search_query=incline+dumbbell+press+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Barbell Bench Press', 'Lie on a flat bench with eyes under the bar. Grip slightly wider than shoulder width. Unrack and lower to mid-chest with elbows at 45 degrees. Press back up to lockout. Perform 6-10 reps with a spotter for heavy sets.', 'strength', 'upper_body', ARRAY['chest','triceps','shoulders'], 'horizontal_push', ARRAY['barbell','bench','rack'], 'full_gym', 'intermediate', false, 'Develops maximal horizontal pressing strength for upper body power and the ability to maintain posture under centrifugal forces.', NULL, 'https://www.youtube.com/results?search_query=barbell+bench+press+form', false, ARRAY['shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Barbell Bent Over Row', 'Hinge at the hips to about 45 degrees with a flat back. Grip the barbell slightly wider than shoulder width. Pull toward your lower ribcage, driving elbows behind you. Lower with control. Perform 8-12 reps with a braced core.', 'strength', 'upper_body', ARRAY['back','lats','biceps','traps','core'], 'horizontal_pull', ARRAY['barbell'], 'full_gym', 'intermediate', false, 'Builds back strength and hip-hinge endurance for maintaining golf posture through a full round with efficient downswing transition.', NULL, 'https://www.youtube.com/results?search_query=barbell+bent+over+row+form', false, ARRAY['lower_back','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pull-ups', 'Hang from a bar with hands slightly wider than shoulders, palms facing away. Pull yourself up until your chin clears the bar by driving elbows down. Lower with full control over 2-3 seconds. Perform 5-10 reps, or use a band for assistance.', 'strength', 'upper_body', ARRAY['lats','biceps','back','forearms','core'], 'vertical_pull', ARRAY['pull_up_bar'], 'full_gym', 'advanced', false, 'The ultimate lat and upper body pulling exercise for back width, grip endurance, and powerful swing mechanics.', NULL, 'https://www.youtube.com/results?search_query=pull+ups+proper+form', false, ARRAY['shoulders','elbows','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Bodyweight Squat', 'Stand with feet shoulder-width apart, toes slightly out. Push hips back and bend knees to lower until thighs are parallel or as low as comfortable. Keep chest up and weight in your heels. Drive back to standing. Perform 15-20 reps.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings','core'], 'squat', ARRAY[]::text[], 'none', 'beginner', true, 'Builds foundational lower body strength for generating ground reaction forces and maintaining the squat-like posture required throughout 18 holes.', NULL, 'https://www.youtube.com/results?search_query=bodyweight+squat+form', true, ARRAY['knees','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Reverse Lunge', 'Stand tall with feet hip-width apart. Step one foot backward and lower until both legs form 90-degree angles. Keep front knee over ankle and torso upright. Drive through front heel to return. Alternate legs for 10-12 reps per side.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings','hip_flexors','core'], 'squat', ARRAY[]::text[], 'none', 'beginner', true, 'Develops single-leg stability and hip flexor flexibility, improving weight transfer balance and reducing lateral sway.', NULL, 'https://www.youtube.com/results?search_query=reverse+lunge+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Single Leg Glute Bridge', 'Lie on your back with one knee bent and foot flat, other leg extended straight. Drive through the grounded foot to lift hips until body forms a straight line. Squeeze glute for 2 seconds. Perform 10-12 reps per side.', 'strength', 'lower_body', ARRAY['glutes','hamstrings','core'], 'hip_hinge', ARRAY[]::text[], 'none', 'intermediate', true, 'Isolates each glute independently to address asymmetrical strength imbalances from the golf swing, building single-leg hip extension power.', NULL, 'https://www.youtube.com/results?search_query=single+leg+glute+bridge+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Wall Sit', 'Lean against a wall with thighs parallel to the floor, knees at 90 degrees. Keep your back pressed flat against the wall. Hold for 30-60 seconds, building to 90 seconds.', 'strength', 'lower_body', ARRAY['quads','glutes','core'], 'squat', ARRAY[]::text[], 'none', 'beginner', true, 'Builds isometric quad endurance essential for maintaining the athletic knee-flex posture throughout a full round without fatigue.', NULL, 'https://www.youtube.com/results?search_query=wall+sit+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Goblet Squat', 'Hold a dumbbell or kettlebell against your chest. Stand with feet slightly wider than shoulders. Squat down keeping the weight close and elbows between knees. Descend until thighs are parallel, then drive up. Perform 10-15 reps.', 'strength', 'lower_body', ARRAY['quads','glutes','core','hamstrings'], 'squat', ARRAY['dumbbells'], 'minimal', 'beginner', true, 'The front-loaded position teaches proper squat mechanics and builds deep squat strength and hip mobility for a powerful golf stance.', NULL, 'https://www.youtube.com/results?search_query=goblet+squat+form', true, ARRAY['knees','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Romanian Deadlift (Dumbbells)', 'Stand holding dumbbells in front of your thighs with a slight knee bend. Hinge at hips and push glutes back, lowering weights along your legs. Lower until you feel a hamstring stretch, then drive hips forward. Perform 10-12 reps.', 'strength', 'lower_body', ARRAY['hamstrings','glutes','back','core'], 'hip_hinge', ARRAY['dumbbells'], 'minimal', 'intermediate', true, 'Strengthens the posterior chain through the hip hinge that mirrors golf posture, building hamstring and glute endurance for maintaining spine angle.', NULL, 'https://www.youtube.com/results?search_query=dumbbell+romanian+deadlift+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Bulgarian Split Squat', 'Stand 2-3 feet in front of a bench. Place your rear foot on the bench behind you. Hold dumbbells at your sides. Lower until front thigh is parallel, keeping torso upright. Drive through front heel. Perform 8-12 reps per side.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings','hip_flexors','core'], 'squat', ARRAY['dumbbells','bench'], 'minimal', 'intermediate', true, 'Develops single-leg strength for powerful weight transfer from trail to lead leg during the downswing while stretching rear hip flexors.', NULL, 'https://www.youtube.com/results?search_query=bulgarian+split+squat+form', false, ARRAY['knees','ankles']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Step-ups', 'Stand facing a sturdy bench at knee height. Step up with one foot, driving through the heel to stand on top. Bring trailing foot up briefly, then lower under control. Hold dumbbells for added resistance. Perform 10-12 reps per side.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings','calves','core'], 'squat', ARRAY['dumbbells','bench'], 'minimal', 'beginner', true, 'Builds single-leg drive strength used to push off the ground during the downswing, improving ground reaction force.', NULL, 'https://www.youtube.com/results?search_query=step+ups+exercise+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Barbell Squat', 'Position barbell across upper traps, feet shoulder-width apart. Brace core, push hips back and bend knees until thighs are parallel. Keep chest up and drive through whole foot. Perform 6-10 reps.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings','core','back'], 'squat', ARRAY['barbell','squat_rack'], 'full_gym', 'intermediate', true, 'The king of lower body exercises, building maximal leg drive for elite ground reaction forces — the primary power source in the modern golf swing.', NULL, 'https://www.youtube.com/results?search_query=barbell+squat+form', false, ARRAY['knees','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Leg Press', 'Sit in the leg press machine with back flat and feet shoulder-width on the platform. Lower the platform until legs reach 90 degrees, then press back up without locking knees. Perform 10-15 reps.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings'], 'squat', ARRAY['leg_press_machine'], 'full_gym', 'beginner', false, 'Joint-friendly heavy lower body strength with back support, ideal for golfers over 40 who need quad and glute power without spinal loading.', NULL, 'https://www.youtube.com/results?search_query=leg+press+form', true, ARRAY['knees','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Barbell Deadlift', 'Stand with feet hip-width, barbell over mid-foot. Hinge and grip bar outside knees. Flatten back, brace core, drive through feet to stand. Pull bar along legs. Perform 5-8 reps, prioritizing form.', 'strength', 'lower_body', ARRAY['hamstrings','glutes','back','core','quads','forearms','traps'], 'hip_hinge', ARRAY['barbell'], 'full_gym', 'advanced', true, 'Develops total-body posterior chain strength that forms the foundation for maintaining golf posture and generating power from the ground.', NULL, 'https://www.youtube.com/results?search_query=barbell+deadlift+form', false, ARRAY['lower_back','knees','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Hip Thrust (Barbell)', 'Sit with upper back against a bench, barbell padded across hips. Plant feet shoulder-width apart. Drive through heels to extend hips until body forms a straight line. Squeeze glutes for 2 seconds. Perform 8-12 reps.', 'strength', 'lower_body', ARRAY['glutes','hamstrings','core'], 'hip_hinge', ARRAY['barbell','bench'], 'full_gym', 'intermediate', true, 'Maximally activates the glutes in hip extension, building the explosive hip thrust that drives pelvis rotation for professional-level clubhead speed.', NULL, 'https://www.youtube.com/results?search_query=barbell+hip+thrust+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Plank', 'Forearm plank with elbows under shoulders, body in a straight line. Engage core and squeeze glutes. Avoid hip sag or pike. Hold 30-60 seconds, building to 90 seconds.', 'strength', 'core', ARRAY['core','shoulders','glutes'], 'anti_rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Builds anti-extension core endurance to resist forces that pull the golfer out of posture, preventing early extension and S-posture TPI faults.', NULL, 'https://www.youtube.com/results?search_query=plank+proper+form', true, ARRAY['shoulders','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Side Plank', 'Lie on your side with forearm on the floor, elbow under shoulder. Stack feet and lift hips, creating a straight line. Hold 20-45 seconds per side. Modify by bending bottom knee.', 'strength', 'core', ARRAY['obliques','core','glutes','shoulders'], 'anti_rotation', ARRAY[]::text[], 'none', 'intermediate', true, 'Strengthens lateral core stabilizers that prevent lateral sway and slide, keeping the pelvis centered during weight transfer.', NULL, 'https://www.youtube.com/results?search_query=side+plank+form', true, ARRAY['shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dead Bug (Basic)', 'Lie on back with arms toward ceiling and knees at 90 degrees above hips. Press lower back into floor. Slowly lower right arm and left leg toward floor, then return and switch. Perform 8-10 reps per side.', 'strength', 'core', ARRAY['core','hip_flexors'], 'anti_rotation', ARRAY[]::text[], 'none', 'beginner', false, 'Builds fundamental anti-extension core control that protects the lower back during loaded movements and teaches proper breathing patterns.', NULL, 'https://www.youtube.com/results?search_query=dead+bug+exercise+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Mountain Climbers', 'Start in high plank. Drive one knee toward chest, then quickly switch legs in a running motion. Keep hips level and core braced. Perform 20-30 reps total at moderate pace.', 'strength', 'core', ARRAY['core','hip_flexors','shoulders','quads'], NULL, ARRAY[]::text[], 'none', 'intermediate', false, 'Combines core stability with cardiovascular conditioning, building stamina to maintain core engagement throughout an entire round.', NULL, 'https://www.youtube.com/results?search_query=mountain+climbers+form', false, ARRAY['wrists','shoulders','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Russian Twist', 'Sit with knees bent, feet slightly elevated, lean back to 45 degrees. Hold a dumbbell at chest level. Rotate torso to touch weight to floor on each side, keeping hips stable. Perform 10-15 reps per side.', 'strength', 'core', ARRAY['obliques','core','hip_flexors'], 'rotation', ARRAY['dumbbells'], 'minimal', 'intermediate', true, 'Directly trains rotational power of the obliques that generates torque in the golf swing.', NULL, 'https://www.youtube.com/results?search_query=russian+twist+form', false, ARRAY['lower_back','neck']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Ab Wheel Rollout', 'Kneel with ab wheel in front. Brace core and slowly roll forward, extending body while maintaining flat back. Pull back by contracting abs. Perform 8-12 reps, starting with limited range.', 'strength', 'core', ARRAY['core','shoulders','lats','hip_flexors'], 'anti_rotation', ARRAY['ab_wheel'], 'minimal', 'advanced', false, 'One of the most demanding anti-extension core exercises, building deep abdominal strength to resist spinal extension forces during high-speed swings.', NULL, 'https://www.youtube.com/results?search_query=ab+wheel+rollout+form', false, ARRAY['lower_back','shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Hanging Leg Raise', 'Hang from a pull-up bar with arms extended. Without swinging, raise legs by curling pelvis upward until thighs are parallel. Lower slowly over 2-3 seconds. Perform 8-12 reps. Modify by bending knees.', 'strength', 'core', ARRAY['core','hip_flexors','obliques','forearms'], NULL, ARRAY['pull_up_bar'], 'full_gym', 'advanced', false, 'Builds lower abdominal and hip flexor strength with grip endurance for core compression power through rotational demands.', NULL, 'https://www.youtube.com/results?search_query=hanging+leg+raise+form', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Farmer''s Carries', 'Stand holding heavy dumbbells at your sides. Brace core, shoulders back and down. Walk with controlled steps for 30-40 meters or 30-45 seconds. Maintain upright posture. Perform 3-4 sets.', 'strength', 'core', ARRAY['core','forearms','traps','shoulders','glutes'], 'carry', ARRAY['dumbbells'], 'minimal', 'beginner', true, 'Builds total-body stabilization, grip endurance, and posture maintenance under load — translating to better posture over 18 holes and consistent grip pressure.', NULL, 'https://www.youtube.com/results?search_query=farmers+carry+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Medicine Ball Rotational Throw', 'Stand sideways to a wall, feet shoulder-width apart, holding a medicine ball at hip level. Rotate your torso away from the wall to load, then explosively rotate and throw the ball into the wall. Catch and repeat. Perform 8-10 reps per side.', 'power', 'rotational', ARRAY['core','obliques','glutes','shoulders'], 'rotation', ARRAY['medicine_ball'], 'minimal', 'intermediate', true, 'Develops explosive rotational power that directly translates to club head speed by training the stretch-shortening cycle through the transverse plane.', NULL, 'https://www.youtube.com/results?search_query=medicine+ball+rotational+throw+golf', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Medicine Ball Slam', 'Stand with feet shoulder-width apart, holding a medicine ball overhead. Forcefully slam the ball into the ground by hinging at the hips and contracting your core. Catch the bounce and repeat. Perform 10-12 reps.', 'power', 'total_body', ARRAY['core','lats','shoulders','glutes','hamstrings'], 'hip_hinge', ARRAY['medicine_ball'], 'minimal', 'intermediate', false, 'Develops total-body explosive power and hip hinge speed, building the aggressive downswing energy that generates distance.', NULL, 'https://www.youtube.com/results?search_query=medicine+ball+slam+form', false, ARRAY['lower_back','shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Medicine Ball Chest Pass', 'Stand facing a wall or partner. Hold a medicine ball at chest level. Explosively push the ball forward, extending arms fully. Catch and repeat. Perform 10-12 reps.', 'power', 'upper_body', ARRAY['chest','shoulders','triceps','core'], 'horizontal_push', ARRAY['medicine_ball'], 'minimal', 'beginner', false, 'Builds upper body pushing power and hand speed that contributes to club head velocity through the impact zone.', NULL, 'https://www.youtube.com/results?search_query=medicine+ball+chest+pass+form', true, ARRAY['shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Box Jumps', 'Stand facing a sturdy box or platform. Bend your knees, swing arms back, then explosively jump onto the box, landing softly with both feet. Stand fully, then step back down. Perform 6-10 reps.', 'power', 'lower_body', ARRAY['quads','glutes','hamstrings','calves','core'], 'squat', ARRAY['plyo_box'], 'minimal', 'intermediate', false, 'Develops lower body explosive power and the ability to generate rapid ground reaction forces, the primary source of power in the golf swing.', NULL, 'https://www.youtube.com/results?search_query=box+jumps+proper+form', false, ARRAY['knees','ankles']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Kettlebell Swing', 'Stand with feet wider than shoulders. Hinge at hips and swing the kettlebell between your legs. Drive hips forward explosively to swing the bell to chest height. Let it swing back and repeat. Perform 12-15 reps.', 'power', 'posterior_chain', ARRAY['glutes','hamstrings','core','shoulders','back'], 'hip_hinge', ARRAY['kettlebell'], 'minimal', 'intermediate', true, 'Trains the explosive hip extension pattern that is the primary engine of the golf swing, building the snap-through power for maximum club head speed.', NULL, 'https://www.youtube.com/results?search_query=kettlebell+swing+form', false, ARRAY['lower_back','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Band-Resisted Rotation', 'Anchor a band at chest height. Stand sideways holding the band at chest level with arms extended. Rotate your torso away from the anchor as fast as possible while maintaining control. Return slowly. Perform 8-10 explosive reps per side.', 'power', 'rotational', ARRAY['core','obliques','shoulders'], 'rotation', ARRAY['resistance_band'], 'minimal', 'intermediate', true, 'Trains high-velocity rotational power against resistance, building the speed-strength needed for maximum club head speed at impact.', NULL, 'https://www.youtube.com/results?search_query=band+resisted+rotation+exercise', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Jump Squat', 'Stand with feet shoulder-width apart. Lower into a quarter squat, then explode upward as high as possible. Land softly by bending your knees to absorb impact. Reset and repeat. Perform 8-10 reps.', 'power', 'lower_body', ARRAY['quads','glutes','hamstrings','calves','core'], 'squat', ARRAY[]::text[], 'none', 'intermediate', false, 'Develops explosive leg power and rate of force development, directly improving the ground reaction forces that drive distance.', NULL, 'https://www.youtube.com/results?search_query=jump+squat+form', false, ARRAY['knees','ankles','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Plyo Push-ups', 'Start in push-up position. Lower yourself, then explosively push off the ground so your hands leave the floor. Land softly and immediately lower into the next rep. Perform 6-8 reps.', 'power', 'upper_body', ARRAY['chest','triceps','shoulders','core'], 'horizontal_push', ARRAY[]::text[], 'none', 'advanced', false, 'Builds upper body explosive power and fast-twitch muscle fiber recruitment for maximum hand speed through impact.', NULL, 'https://www.youtube.com/results?search_query=plyometric+push+ups+form', false, ARRAY['wrists','shoulders','elbows']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Speed Deadlift', 'Set up like a conventional deadlift with moderate weight (50-60% max). Pull explosively, driving through the floor as fast as possible while maintaining form. Lower under control. Perform 5-6 reps with maximum bar speed.', 'power', 'posterior_chain', ARRAY['hamstrings','glutes','back','core','quads'], 'hip_hinge', ARRAY['barbell'], 'full_gym', 'advanced', false, 'Develops rate of force development in the posterior chain, building the explosive hip drive that translates directly to swing power.', NULL, 'https://www.youtube.com/results?search_query=speed+deadlift+form', false, ARRAY['lower_back','knees','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Broad Jump', 'Stand with feet shoulder-width apart. Bend knees and swing arms back, then explode forward and upward, jumping as far as possible. Land softly on both feet with knees bent. Reset and repeat. Perform 5-8 reps.', 'power', 'lower_body', ARRAY['quads','glutes','hamstrings','calves','core'], 'squat', ARRAY[]::text[], 'none', 'intermediate', false, 'Develops horizontal power production and the ability to drive force through the ground, improving the thrust mechanics of the downswing.', NULL, 'https://www.youtube.com/results?search_query=broad+jump+exercise+form', false, ARRAY['knees','ankles']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Walking (Treadmill/Outdoor)', 'Walk at a brisk pace (3-4 mph) for 20-45 minutes. Maintain upright posture with arms swinging naturally. Can be done on a treadmill or outdoors. Add incline for increased challenge.', 'cardio', 'aerobic', ARRAY['quads','hamstrings','calves','glutes','core'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Builds the cardiovascular endurance needed to maintain focus and energy throughout 18 holes of walking golf (approximately 5 miles).', NULL, 'https://www.youtube.com/results?search_query=brisk+walking+for+fitness', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Stationary Bike', 'Cycle at moderate intensity for 20-30 minutes, maintaining 60-80 RPM. Adjust resistance to maintain a challenging but sustainable pace. Can use upright or recumbent bike.', 'cardio', 'aerobic', ARRAY['quads','hamstrings','calves','glutes'], NULL, ARRAY['stationary_bike'], 'home_gym', 'beginner', false, 'Low-impact cardiovascular conditioning that builds leg endurance without joint stress, ideal for active recovery days.', NULL, 'https://www.youtube.com/results?search_query=stationary+bike+workout+beginners', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Rowing Machine', 'Row at moderate intensity for 15-25 minutes. Focus on driving with your legs first, then pulling with your back. Maintain a controlled pace and proper form throughout.', 'cardio', 'aerobic', ARRAY['back','lats','quads','hamstrings','core','biceps','shoulders'], 'horizontal_pull', ARRAY['rowing_machine'], 'home_gym', 'beginner', true, 'Full-body conditioning that strengthens the posterior chain while building endurance, with a hip hinge motion that reinforces golf posture.', NULL, 'https://www.youtube.com/results?search_query=rowing+machine+form+beginners', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Jump Rope', 'Jump rope at a moderate pace, staying on the balls of your feet with minimal ground clearance. Keep elbows close and rotate from the wrists. Start with 1-2 minutes, building to 10-15 minutes.', 'cardio', 'aerobic', ARRAY['calves','quads','shoulders','core'], NULL, ARRAY['jump_rope'], 'minimal', 'intermediate', false, 'Develops foot speed, coordination, and cardiovascular fitness while building calf and ankle strength for stability.', NULL, 'https://www.youtube.com/results?search_query=jump+rope+beginners+form', false, ARRAY['knees','ankles']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Battle Ropes', 'Hold the ends of a heavy rope with both hands. Create alternating waves by rapidly raising and lowering each arm. Maintain a quarter squat and braced core throughout. Perform 20-30 second bursts with rest between.', 'cardio', 'hiit', ARRAY['shoulders','core','forearms','back','glutes'], NULL, ARRAY['battle_ropes'], 'home_gym', 'intermediate', false, 'High-intensity conditioning that builds grip endurance, shoulder stamina, and total-body work capacity.', NULL, 'https://www.youtube.com/results?search_query=battle+ropes+exercise+form', false, ARRAY['shoulders','wrists']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Sled Push', 'Load a sled with appropriate weight. Drive the sled forward by pushing with arms extended, driving through your legs with powerful steps. Keep your core braced and body at a 45-degree lean. Push for 20-30 meters per set.', 'cardio', 'hiit', ARRAY['quads','glutes','hamstrings','core','shoulders','calves'], NULL, ARRAY['sled'], 'full_gym', 'intermediate', false, 'Develops leg drive power and cardiovascular conditioning simultaneously, building the pushing strength that generates ground reaction forces.', NULL, 'https://www.youtube.com/results?search_query=sled+push+exercise+form', true, ARRAY['lower_back','knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Stair Climber', 'Use a stair climbing machine at moderate intensity for 15-25 minutes. Maintain upright posture and avoid leaning heavily on the handrails. Vary speed for interval training.', 'cardio', 'aerobic', ARRAY['quads','glutes','calves','hamstrings'], NULL, ARRAY['stair_climber'], 'full_gym', 'beginner', false, 'Low-impact cardio that builds leg endurance and strengthens the muscles used for walking hilly golf courses.', NULL, 'https://www.youtube.com/results?search_query=stair+climber+machine+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Swimming/Pool Walking', 'Swim laps at a moderate pace using freestyle or backstroke for 20-30 minutes. Alternatively, walk laps in waist-deep water for joint-friendly cardio conditioning.', 'cardio', 'aerobic', ARRAY['shoulders','back','core','quads','hamstrings','glutes'], NULL, ARRAY['pool'], 'full_gym', 'beginner', false, 'Zero-impact full-body conditioning that builds shoulder endurance and cardiovascular fitness while being completely joint-friendly.', NULL, 'https://www.youtube.com/results?search_query=swimming+for+fitness+beginners', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Standing Hamstring Stretch', 'Stand and place one heel on a low surface. Keep your leg straight and hinge forward from the hips until you feel a stretch behind the knee and thigh. Hold for 30-45 seconds per side.', 'flexibility', 'lower_body', ARRAY['hamstrings'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Maintains hamstring length needed for a comfortable golf address position and healthy lower back.', NULL, 'https://www.youtube.com/results?search_query=standing+hamstring+stretch+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Doorway Chest Stretch', 'Stand in a doorway with your forearms on each side of the frame at shoulder height. Step one foot forward and lean through until you feel a stretch across your chest and front shoulders. Hold for 30-45 seconds.', 'flexibility', 'upper_body', ARRAY['chest','shoulders'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Opens the chest and anterior shoulders to counteract forward-rounded posture, improving ability to maintain a wide swing arc.', NULL, 'https://www.youtube.com/results?search_query=doorway+chest+stretch+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Cross-Body Shoulder Stretch', 'Stand or sit and bring one arm across your body at chest height. Use the opposite hand to gently pull the arm closer to your chest until you feel a stretch in the back of the shoulder. Hold 30 seconds per side.', 'flexibility', 'upper_body', ARRAY['shoulders','back'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Stretches the posterior deltoid and shoulder capsule for better arm positioning during the backswing.', NULL, 'https://www.youtube.com/results?search_query=cross+body+shoulder+stretch+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Seated Piriformis Stretch', 'Sit on the floor with one leg extended. Cross the other foot over the extended knee. Hug the crossed knee toward the opposite shoulder until you feel a deep glute stretch. Hold for 30-45 seconds per side.', 'flexibility', 'lower_body', ARRAY['glutes','hip_flexors'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Relieves piriformis tension that can cause sciatica-like symptoms and restrict hip rotation needed for the swing.', NULL, 'https://www.youtube.com/results?search_query=seated+piriformis+stretch+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Standing Calf Stretch', 'Stand facing a wall with hands on the wall. Step one foot back keeping it straight with heel on the floor. Lean into the wall until you feel a stretch in the back calf. Hold 30 seconds per side. Bend the back knee slightly to target the soleus.', 'flexibility', 'lower_body', ARRAY['calves'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Maintains ankle dorsiflexion range needed for a stable stance and proper knee flex in the golf setup.', NULL, 'https://www.youtube.com/results?search_query=standing+calf+stretch+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Child''s Pose', 'Kneel on the floor, sit your hips back toward your heels, and extend your arms forward on the floor. Rest your forehead on the ground and breathe deeply. Hold for 30-60 seconds. Walk hands to each side for a lateral stretch variation.', 'flexibility', 'full_body', ARRAY['back','shoulders','hip_flexors','lats'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'A restorative stretch that decompresses the spine and relaxes the back muscles after rotational training or a long round.', NULL, 'https://www.youtube.com/results?search_query=child+pose+stretch+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Thread the Needle', 'Start on hands and knees. Reach one arm under your body and across toward the opposite side, lowering your shoulder and head toward the floor. Hold for 20-30 seconds, then return and reach the same arm toward the ceiling. Perform 5-6 reps per side.', 'flexibility', 'thoracic', ARRAY['back','shoulders','obliques'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Combines thoracic rotation with a gentle stretch of the upper back and shoulders, improving the rotational range needed for a full backswing.', NULL, 'https://www.youtube.com/results?search_query=thread+the+needle+stretch+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Lying IT Band Stretch', 'Lie on your back. Cross one leg over the other and let it fall to the opposite side while keeping both shoulders on the floor. Gently pull the crossed leg with the opposite hand. Hold 30-45 seconds per side.', 'flexibility', 'lower_body', ARRAY['glutes','abductors','hip_flexors'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Releases IT band tension that can cause lateral knee pain and restrict hip mobility during the swing.', NULL, 'https://www.youtube.com/results?search_query=lying+IT+band+stretch+form', true, ARRAY['knees','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Wrist Flexor/Extensor Stretch', 'Extend one arm in front with palm facing up. Use the other hand to gently pull fingers down and back for a wrist flexor stretch. Then flip palm down and pull fingers toward you for extensor stretch. Hold each 20-30 seconds per side.', 'flexibility', 'upper_body', ARRAY['forearms'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Maintains wrist mobility and prevents golfer''s elbow by stretching the forearm muscles stressed during grip and impact.', NULL, 'https://www.youtube.com/results?search_query=wrist+flexor+extensor+stretch', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Seated Forward Fold', 'Sit on the floor with legs extended straight in front. Reach forward toward your toes, hinging from the hips rather than rounding the back. Hold for 30-45 seconds. Use a towel around feet if needed.', 'flexibility', 'posterior_chain', ARRAY['hamstrings','back','calves'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Stretches the entire posterior chain that can become tight from both sitting and golf, supporting healthy spinal flexion.', NULL, 'https://www.youtube.com/results?search_query=seated+forward+fold+stretch+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Single Leg Stand', 'Stand on one foot with the other foot lifted slightly off the ground. Maintain balance for 30-60 seconds per side. Progress by closing your eyes or standing on a soft surface.', 'balance', 'static', ARRAY['core','glutes','calves'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Develops proprioceptive awareness and ankle stability needed for a balanced, consistent golf swing on any terrain.', NULL, 'https://www.youtube.com/results?search_query=single+leg+balance+exercise', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Single Leg Romanian Deadlift', 'Stand on one leg with a slight knee bend, holding a dumbbell in the opposite hand. Hinge at the hip, extending the free leg behind you for counterbalance, and lower the weight toward the floor. Return to standing. Perform 8-10 reps per side.', 'balance', 'dynamic', ARRAY['hamstrings','glutes','core','back'], 'hip_hinge', ARRAY['dumbbells'], 'minimal', 'intermediate', true, 'Combines balance, hip hinge strength, and single-leg stability — all critical for maintaining posture on uneven lies and during weight transfer.', NULL, 'https://www.youtube.com/results?search_query=single+leg+romanian+deadlift+form', false, ARRAY['lower_back','ankles']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('BOSU Ball Squats', 'Stand on the flat side of a BOSU ball (dome side down). Perform slow, controlled squats while maintaining balance. Start with quarter squats and progress deeper. Perform 10-12 reps.', 'balance', 'dynamic', ARRAY['quads','glutes','core','calves'], 'squat', ARRAY['bosu_ball'], 'minimal', 'intermediate', false, 'Challenges stability on an unstable surface, building the reflexive muscle activation needed for a balanced swing.', NULL, 'https://www.youtube.com/results?search_query=bosu+ball+squat+form', false, ARRAY['knees','ankles']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Tandem Walk', 'Walk forward placing the heel of your front foot directly against the toes of your back foot with each step. Keep gaze forward, arms at sides. Walk 20-30 steps. Maintain upright posture.', 'balance', 'gait', ARRAY['core','calves','glutes'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Develops vestibular balance and postural control for steady head position and stable swing mechanics.', NULL, 'https://www.youtube.com/results?search_query=tandem+walk+balance+exercise', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Single Leg Calf Raise', 'Stand on one foot on a step or flat ground. Rise up onto your toes as high as possible, pause at the top, then lower slowly below the starting height for a stretch. Perform 12-15 reps per side.', 'balance', 'single_leg', ARRAY['calves','core'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Builds calf strength and ankle stability that supports proper ground contact and balance throughout the swing.', NULL, 'https://www.youtube.com/results?search_query=single+leg+calf+raise+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Star Balance Reach', 'Stand on one leg and reach the opposite foot out in front, to the side, and behind you in a star pattern while maintaining balance. Lightly touch the ground at each point and return to center. Perform 5-6 complete stars per side.', 'balance', 'dynamic', ARRAY['core','glutes','quads','hamstrings','calves'], NULL, ARRAY[]::text[], 'none', 'intermediate', false, 'Challenges multi-directional balance and proprioception, building stability needed for maintaining posture on uneven lies.', NULL, 'https://www.youtube.com/results?search_query=star+balance+reach+exercise', false, ARRAY['ankles','knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Heel-to-Toe Walk', 'Walk forward placing the heel of each foot directly against the toes of the other foot. Keep gaze forward and arms at sides for 20-30 steps. Maintain upright posture throughout.', 'balance', 'gait', ARRAY['core','calves','glutes'], NULL, ARRAY[]::text[], 'none', 'beginner', false, 'Develops vestibular balance and gait control for steady head position and balanced walking on the course.', NULL, 'https://www.youtube.com/results?search_query=heel+to+toe+walk+balance', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Stability Ball Plank', 'Place your forearms on a stability ball and extend your legs behind you into a plank. Maintain a straight line from head to heels while resisting the ball''s movement. Hold for 20-40 seconds.', 'balance', 'core', ARRAY['core','shoulders','glutes'], 'anti_rotation', ARRAY['stability_ball'], 'minimal', 'intermediate', false, 'Trains core stability on an unstable surface, building reflexive anti-rotation strength for a consistent swing.', NULL, 'https://www.youtube.com/results?search_query=stability+ball+plank+form', false, ARRAY['shoulders','lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Pallof Press (Cable Anti-Rotation)', 'Stand sideways to a cable set at chest height. Hold handle at chest with both hands. Press straight out, resisting the cable''s rotational pull. Hold 2-3 seconds and return. Perform 10-12 reps per side.', 'golf_specific', 'stability', ARRAY['core','obliques','shoulders'], 'anti_rotation', ARRAY['cable_machine'], 'minimal', 'intermediate', true, 'Trains the core to resist rotational forces — the foundation for generating and controlling power in the golf swing without energy leaks.', 'stability', 'https://www.youtube.com/results?search_query=pallof+press+cable+anti+rotation', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Lateral Band Walks', 'Place a mini band above your knees. Stand in a quarter squat, feet hip-width creating tension. Step laterally 10-15 steps each direction, maintaining constant band tension and squat depth.', 'golf_specific', 'hip_stability', ARRAY['glutes','abductors','quads'], NULL, ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Activates the gluteus medius for hip stability, preventing lateral sway and the common TPI fault of excessive lateral movement.', 'strength', 'https://www.youtube.com/results?search_query=lateral+band+walks+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Clamshells', 'Lie on your side with knees bent 45 degrees, mini band above knees. Keeping feet together, open top knee like a clamshell against band resistance. Perform 15-20 reps per side with a pause at the top.', 'golf_specific', 'hip_stability', ARRAY['glutes','abductors','hip_flexors'], NULL, ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Isolates external hip rotators that control pelvic stability during rotation, preventing early extension and loss of posture.', 'stability', 'https://www.youtube.com/results?search_query=clamshell+exercise+band+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Single Arm Cable Row with Rotation', 'Face a cable at mid-height. Pull handle toward your hip while rotating torso away from the machine. Squeeze shoulder blade and hold, then return with control. Keep hips stable. Perform 10-12 reps per side.', 'golf_specific', 'rotational_strength', ARRAY['back','lats','obliques','core','biceps'], 'rotation', ARRAY['cable_machine'], 'minimal', 'intermediate', true, 'Combines pulling strength with rotational movement, mimicking the trail arm action during the downswing.', 'strength', 'https://www.youtube.com/results?search_query=single+arm+cable+row+rotation', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Medicine Ball Golf Swing', 'Stand in golf address position with a 4-8 lb medicine ball. Perform a full swing motion, rotating back and explosively through to a finish. Release the ball toward target. Focus on hip-torso-arms sequencing. Perform 8-10 reps per side.', 'golf_specific', 'swing_training', ARRAY['core','obliques','glutes','shoulders','hip_flexors'], 'rotation', ARRAY['medicine_ball'], 'minimal', 'intermediate', true, 'The most golf-specific power exercise, training the exact rotational sequence with added resistance for increased club head speed.', 'power', 'https://www.youtube.com/results?search_query=medicine+ball+golf+swing+exercise', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Hip Flexor Stretch with Rotation', 'Half-kneel with front foot flat, back knee on pad. Squeeze back-side glute to stretch hip flexor. Rotate torso toward front knee, reaching arm overhead. Hold 30 seconds per side.', 'golf_specific', 'hip_mobility', ARRAY['hip_flexors','obliques','core'], 'rotation', ARRAY[]::text[], 'none', 'beginner', true, 'Combines hip flexor lengthening with thoracic rotation, addressing the two most common mobility restrictions in golfers over 40.', 'mobility', 'https://www.youtube.com/results?search_query=hip+flexor+stretch+rotation+golf', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Thoracic Extension over Foam Roller', 'Lie face-up with foam roller under mid-back. Hands behind head. Gently extend over the roller, opening chest toward ceiling. Hold 5 seconds, curl up. Move roller to different segments and repeat.', 'golf_specific', 'thoracic_mobility', ARRAY['back','core'], NULL, ARRAY['foam_roller'], 'minimal', 'beginner', true, 'Restores thoracic extension critical for full shoulder turn. A stiff T-spine forces compensatory lower back and hip rotation leading to pain.', 'mobility', 'https://www.youtube.com/results?search_query=thoracic+extension+foam+roller+golf', true, ARRAY['neck']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Standing Y-T-W Raises', 'Stand with slight hip hinge, chest facing floor at 45 degrees. With light dumbbells or no weight, raise arms into Y overhead, lower. Then T to sides, lower. Then W with elbows bent and squeezed back. Perform 8-10 reps each.', 'golf_specific', 'shoulder_stability', ARRAY['shoulders','rotator_cuff','traps','back'], NULL, ARRAY['dumbbells'], 'minimal', 'beginner', true, 'Strengthens scapular stabilizers and rotator cuff in multiple planes, building shoulder health for a repeatable swing.', 'stability', 'https://www.youtube.com/results?search_query=Y+T+W+raises+exercise+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Prone I-Y-T Raises', 'Lie face-down on floor or bench with arms hanging. Raise arms into I (overhead), Y (45 degrees), and T (sides) positions with thumbs up. Lift to shoulder height, squeeze shoulder blades, hold 2 seconds. Perform 8-10 reps each.', 'golf_specific', 'shoulder_stability', ARRAY['shoulders','rotator_cuff','traps','back'], NULL, ARRAY[]::text[], 'none', 'beginner', true, 'Targets lower trapezius and posterior shoulder muscles that are chronically weak in golfers, improving scapular control.', 'stability', 'https://www.youtube.com/results?search_query=prone+I+Y+T+raises+form', true, ARRAY['shoulders','neck']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Shoulder External Rotation with Band', 'Stand with elbow pinned to side, bent 90 degrees. Hold band anchored at waist height on opposite side. Rotate forearm outward against band resistance, keeping elbow glued to ribs. Perform 12-15 reps per side.', 'golf_specific', 'shoulder_health', ARRAY['rotator_cuff','shoulders'], NULL, ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Strengthens infraspinatus and teres minor that decelerate the arm during follow-through — the leading cause of shoulder injury in golfers.', 'stability', 'https://www.youtube.com/results?search_query=shoulder+external+rotation+band+form', true, ARRAY['shoulders','elbows']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Face Pulls with Band', 'Anchor band at face height. Pull toward face with elbows high and wide, rotating hands outward at end. Squeeze upper back. Perform 15-20 reps.', 'strength', 'upper_body', ARRAY['shoulders','rotator_cuff','traps','back'], 'horizontal_pull', ARRAY['resistance_band'], 'minimal', 'beginner', true, 'Strengthens posterior shoulder and external rotators, providing critical injury prevention for the repetitive golf swing.', NULL, 'https://www.youtube.com/results?search_query=face+pulls+band+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Lateral Raises', 'Stand with light dumbbells at sides. Raise arms out to sides until parallel with floor, leading with elbows. Lower slowly under control. Perform 12-15 reps.', 'strength', 'upper_body', ARRAY['shoulders'], NULL, ARRAY['dumbbells'], 'minimal', 'beginner', false, 'Builds lateral deltoid strength for balanced shoulder development and reduced fatigue during long rounds.', NULL, 'https://www.youtube.com/results?search_query=lateral+raises+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Front Raises', 'Stand holding dumbbells in front of thighs, palms facing body. Raise arms straight in front to shoulder height. Lower slowly. Perform 10-12 reps. Avoid using momentum.', 'strength', 'upper_body', ARRAY['shoulders','core'], NULL, ARRAY['dumbbells'], 'minimal', 'beginner', false, 'Strengthens anterior deltoids for balanced shoulder development and arm elevation during the backswing.', NULL, 'https://www.youtube.com/results?search_query=front+raises+dumbbell+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Hammer Curls', 'Stand holding dumbbells at sides with palms facing each other (neutral grip). Curl toward shoulders keeping neutral wrist position. Lower under control. Perform 10-12 reps.', 'strength', 'upper_body', ARRAY['biceps','forearms'], NULL, ARRAY['dumbbells'], 'minimal', 'beginner', false, 'Builds bicep and brachioradialis strength with a neutral grip that is easier on elbows and wrists, improving grip endurance.', NULL, 'https://www.youtube.com/results?search_query=hammer+curls+form', true, ARRAY['elbows']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Tricep Dips', 'Hands on bench edge behind you, fingers forward. Slide hips off bench and lower by bending elbows to 90 degrees. Push through palms to extend. Keep back close to bench. Perform 8-12 reps.', 'strength', 'upper_body', ARRAY['triceps','shoulders','chest'], 'vertical_push', ARRAY['bench'], 'minimal', 'intermediate', false, 'Develops tricep pushing strength for arm extension speed through the impact zone of the golf swing.', NULL, 'https://www.youtube.com/results?search_query=tricep+dips+bench+form', false, ARRAY['shoulders','wrists','elbows']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Inverted Rows', 'Set barbell in rack at waist height. Hang underneath with arms extended, body straight. Pull chest to bar squeezing shoulder blades. Lower under control. Adjust body angle for difficulty. Perform 8-12 reps.', 'strength', 'upper_body', ARRAY['back','lats','biceps','core','traps'], 'horizontal_pull', ARRAY['barbell','rack'], 'home_gym', 'beginner', false, 'Joint-friendly horizontal pulling that strengthens the upper back and reinforces the anti-extension demands of golf posture.', NULL, 'https://www.youtube.com/results?search_query=inverted+rows+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Dumbbell Chest Flyes', 'Lie on flat bench with dumbbells above chest, palms facing each other. With slight elbow bend, lower weights out to sides in an arc until you feel a chest stretch. Squeeze chest to return. Perform 10-12 reps.', 'strength', 'upper_body', ARRAY['chest','shoulders'], 'horizontal_push', ARRAY['dumbbells','bench'], 'home_gym', 'intermediate', false, 'Stretches and strengthens pectoral muscles through full range, improving chest flexibility for a full backswing.', NULL, 'https://www.youtube.com/results?search_query=dumbbell+chest+flyes+form', false, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Single Arm Dumbbell Row', 'One hand and knee on bench for support. Hold dumbbell in free hand, arm extended. Pull toward hip driving elbow past torso. Squeeze shoulder blade. Lower with control. Perform 10-12 reps per side.', 'strength', 'upper_body', ARRAY['back','lats','biceps','core'], 'horizontal_pull', ARRAY['dumbbells','bench'], 'minimal', 'beginner', true, 'Builds unilateral pulling strength and anti-rotation core stability, correcting muscle imbalances from the one-sided golf swing.', NULL, 'https://www.youtube.com/results?search_query=single+arm+dumbbell+row+form', true, ARRAY['lower_back']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Seated Calf Raises', 'Sit with balls of feet on a raised surface, weight across knees. Raise heels as high as possible, pause, then lower below platform for full stretch. Perform 15-20 reps.', 'strength', 'lower_body', ARRAY['calves'], NULL, ARRAY['dumbbells','bench'], 'minimal', 'beginner', false, 'Targets the soleus for ankle stability and endurance during prolonged walking and standing on the course.', NULL, 'https://www.youtube.com/results?search_query=seated+calf+raises+form', true, ARRAY[]::text[]);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Leg Curls', 'Lie face-down on leg curl machine with pad behind ankles. Curl weight toward glutes by bending knees. Squeeze hamstrings at top. Lower slowly. Perform 10-12 reps.', 'strength', 'lower_body', ARRAY['hamstrings'], NULL, ARRAY['leg_curl_machine'], 'full_gym', 'beginner', false, 'Isolates hamstrings for knee flexion strength that stabilizes the lower body and protects knees during the swing.', NULL, 'https://www.youtube.com/results?search_query=leg+curls+machine+form', true, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Leg Extensions', 'Sit on leg extension machine with pad on front of ankles. Extend legs by straightening knees. Squeeze quads at top, then lower slowly. Avoid aggressive lockout. Perform 12-15 reps.', 'strength', 'lower_body', ARRAY['quads'], NULL, ARRAY['leg_extension_machine'], 'full_gym', 'beginner', false, 'Isolates quadriceps for knee extension strength needed to maintain address posture and stability throughout the swing.', NULL, 'https://www.youtube.com/results?search_query=leg+extensions+form', false, ARRAY['knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Landmine Press', 'Hold end of barbell anchored in landmine at shoulder height with one hand. Press up and forward at an angle. Lower under control. Staggered stance for stability. Perform 8-10 reps per side.', 'strength', 'upper_body', ARRAY['shoulders','chest','triceps','core'], 'vertical_push', ARRAY['barbell','landmine_attachment'], 'home_gym', 'intermediate', true, 'Shoulder-friendly angled pressing that builds overhead strength while training core stability similar to the golf swing.', NULL, 'https://www.youtube.com/results?search_query=landmine+press+form', true, ARRAY['shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Landmine Rotation', 'Hold end of barbell anchored in landmine at chest height with both hands, arms extended. Rotate bar from one hip to the other in an arc, pivoting feet. Drive rotation from hips and core. Perform 8-10 reps per side.', 'strength', 'core', ARRAY['core','obliques','shoulders','glutes'], 'rotation', ARRAY['barbell','landmine_attachment'], 'home_gym', 'intermediate', true, 'Loaded rotation exercise that trains the full-body rotational pattern of the golf swing with progressive resistance.', NULL, 'https://www.youtube.com/results?search_query=landmine+rotation+exercise+form', false, ARRAY['lower_back','shoulders']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Turkish Get-Up', 'Lie on back holding kettlebell with one arm locked out overhead. Through a precise sequence, transition from lying to standing while keeping weight overhead. Reverse to return. Keep eyes on weight. Perform 2-3 reps per side.', 'strength', 'full_body', ARRAY['core','shoulders','glutes','quads','hip_flexors'], NULL, ARRAY['kettlebell'], 'minimal', 'advanced', true, 'The ultimate full-body stability and mobility exercise, training shoulder stability, hip mobility, and body awareness in a single movement.', NULL, 'https://www.youtube.com/results?search_query=turkish+get+up+form', false, ARRAY['shoulders','wrists','knees']);
INSERT INTO public.exercises (name, description, category, subcategory, muscle_groups, movement_pattern, equipment_needed, equipment_tier, difficulty, is_golf_specific, golf_benefit, tpi_category, video_url, is_joint_friendly, contraindicated_areas) VALUES
('Trap Bar Deadlift', 'Stand inside trap bar, feet hip-width. Grip handles, brace core. Drive through feet to stand, extending hips and knees. Keep chest up and back flat. Lower under control. Perform 6-10 reps.', 'strength', 'lower_body', ARRAY['quads','glutes','hamstrings','back','core','forearms'], 'hip_hinge', ARRAY['trap_bar'], 'full_gym', 'intermediate', true, 'Spine-friendly deadlift variation with centered load, building total-body posterior chain strength — the engine of the golf swing.', NULL, 'https://www.youtube.com/results?search_query=trap+bar+deadlift+form', false, ARRAY['lower_back','knees']);
